<?php
$pdo=db();$scales=$pdo->query('SELECT id,name,level,active FROM grading_scales ORDER BY level,name')->fetchAll();$selectedScale=filter_var($_GET['scale_id']??null,FILTER_VALIDATE_INT);if(!$selectedScale&&$scales)$selectedScale=(int)$scales[0]['id'];$bands=[];$currentScale=null;foreach($scales as $scale)if((int)$scale['id']===$selectedScale)$currentScale=$scale;if($currentScale){$stmt=$pdo->prepare('SELECT * FROM grading_bands WHERE scale_id=:id ORDER BY lower_percentage DESC');$stmt->execute(['id'=>$selectedScale]);$bands=$stmt->fetchAll();}
?>
<section class="panel info-panel academic-note"><h2>School grading scales</h2><p>Set the grade labels and percentage ranges approved by your school. The portal does not install assumed ZIMSEC boundaries. A learner report uses the active scale for that learner’s O-Level or A-Level form.</p></section>
<div class="academic-two-col"><section class="panel settings-panel"><h2>Create a grading scale</h2><form method="post" action="actions/grading_scale_save.php" class="compact-form"><?= csrf_field() ?><input type="hidden" name="operation" value="create_scale"><label>Scale name<input name="name" maxlength="100" required placeholder="School O-Level scale"></label><label>Applies to<select name="level"><option>O-Level</option><option>A-Level</option></select></label><button class="primary-button">Create scale</button></form></section>
<?php if($currentScale): ?><section class="panel settings-panel"><h2>Add a grade band</h2><form method="post" action="actions/grading_scale_save.php" class="compact-form"><?= csrf_field() ?><input type="hidden" name="operation" value="save_band"><input type="hidden" name="scale_id" value="<?= (int)$currentScale['id'] ?>"><label>Grade label<input name="grade" maxlength="16" required placeholder="A"></label><label>Minimum percent<input type="number" name="lower_percentage" min="0" max="100" step="0.01" required></label><label>Maximum percent<input type="number" name="upper_percentage" min="0" max="100" step="0.01" required></label><label>Description<input name="description" maxlength="120" placeholder="Excellent"></label><button class="primary-button">Add grade band</button></form></section><?php endif; ?></div>
<section class="panel learners-panel"><div class="panel-heading"><div><h2>Configured scales</h2><p>Every band must have a unique, non-overlapping percentage range.</p></div></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Scale</th><th>Level</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($scales as $scale): ?><tr><td><a class="text-button" href="?page=academics&tab=grading&scale_id=<?= (int)$scale['id'] ?>"><?= h($scale['name']) ?></a></td><td><?= h($scale['level']) ?></td><td><?= $scale['active']?'Active':'Inactive' ?></td><td><form method="post" action="actions/grading_scale_save.php"><?= csrf_field() ?><input type="hidden" name="operation" value="toggle_scale"><input type="hidden" name="scale_id" value="<?= (int)$scale['id'] ?>"><input type="hidden" name="active" value="<?= $scale['active']?0:1 ?>"><button class="text-button"><?= $scale['active']?'Deactivate':'Activate' ?></button></form></td></tr><?php endforeach; if(!$scales): ?><tr><td colspan="4" class="empty-cell">Create a scale and enter the school-approved percentage bands to enable grades on reports.</td></tr><?php endif; ?></tbody></table></div></section>
<?php if($currentScale): ?><section class="panel learners-panel"><div class="panel-heading"><div><h2><?= h($currentScale['name']) ?> bands</h2><p><?= h($currentScale['level']) ?></p></div></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Grade</th><th>Range</th><th>Description</th></tr></thead><tbody><?php foreach($bands as $band): ?><tr><td><b><?= h($band['grade']) ?></b></td><td><?= number_format((float)$band['lower_percentage'],2) ?>% – <?= number_format((float)$band['upper_percentage'],2) ?>%</td><td><?= h($band['description']?:'—') ?></td></tr><?php endforeach; if(!$bands): ?><tr><td colspan="3" class="empty-cell">No bands have been configured for this scale yet.</td></tr><?php endif; ?></tbody></table></div></section><?php endif; ?>
